// Function declaration (hoisted)
function add(a, b) { return a + b; }

// Function expression (not hoisted)
const multiply = function(a, b) { return a * b; };

// Arrow function — shorter, no own 'this'
const square = x => x * x;
const sum = (a, b) => a + b;
const greet = name => {
    const msg = `Hello, ${name}!`;
    return msg;
};

// Default parameters
const connect = (host = 'localhost', port = 3000) => `${host}:${port}`;

// Rest parameters
const total = (...nums) => nums.reduce((a, b) => a + b, 0);
total(1, 2, 3, 4);  // 10

// Closure — inner function remembers outer scope
function counter(start = 0) {
    let count = start;
    return {
        increment: () => ++count,
        decrement: () => --count,
        value: () => count
    };
}
const c = counter(10);
c.increment();
c.increment();
console.log(c.value());  // 12

// IIFE — Immediately Invoked Function Expression
(function() {
    const private = 'scoped';
    console.log(private);
})();
