// Promise basics
const p = new Promise((resolve, reject) => {
    setTimeout(() => resolve('done!'), 1000);
});

p.then(result => console.log(result))
 .catch(err  => console.error(err))
 .finally(()  => console.log('always runs'));

// Promise combinators
Promise.all([p1, p2, p3])           // wait for ALL — rejects if any fails
Promise.allSettled([p1, p2, p3])    // wait for ALL — never rejects
Promise.race([p1, p2])              // first one wins
Promise.any([p1, p2])               // first to RESOLVE wins

// async/await — syntactic sugar over Promises
async function fetchUser(id) {
    try {
        const response = await fetch(`/api/users/${id}`);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const data = await response.json();
        return data;
    } catch (err) {
        console.error('Failed:', err);
        throw err;
    }
}

// Parallel requests (not sequential!)
async function fetchAll(ids) {
    const promises = ids.map(id => fetchUser(id));
    const users = await Promise.all(promises);
    return users;
}

// Top-level await (ES2022)
const data = await fetchUser(1);
