class Animal {
    #name;              // private field (ES2022)
    static count = 0;  // static field

    constructor(name, age) {
        this.#name = name;
        this.age = age;
        Animal.count++;
    }

    get name() { return this.#name; }  // getter
    set name(v) {
        if (typeof v !== 'string') throw new TypeError('string expected');
        this.#name = v;
    }

    speak() { return `${this.#name} makes a sound`; }

    static getCount() { return Animal.count; }

    toString() { return `Animal(${this.#name}, ${this.age})`; }
}

class Dog extends Animal {
    constructor(name, age, breed) {
        super(name, age);
        this.breed = breed;
    }

    speak() { return `${this.name} barks!`; }  // override
}

const d = new Dog('Rex', 3, 'Lab');
console.log(d.speak());              // Rex barks!
console.log(d instanceof Animal);    // true
console.log(Animal.getCount());      // 1
