function add(a, b) { return a + b; }
module.exports = { PI, add };

// main.js
const { PI, add } = require('./math');

// package.json — choose module system
// { "type": "module" }   → ESM
// { "type": "commonjs" } → CJS (default)

// Re-export
export { add } from './math.js';
export * from './math.js';
